import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Iridium","description":"","frontmatter":{"title":"Iridium","order":2},"headers":[],"relativePath":"mods/iridium.md","filePath":"mods/iridium.md","lastUpdated":1786957039000}'),r={name:"mods/iridium.md"};function s(l,e,n,d,u,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="iridium" tabindex="-1">Iridium <a class="header-anchor" href="#iridium" aria-label="Permalink to &quot;Iridium&quot;">​</a></h1><blockquote><p>An <strong>optimization Mod</strong> for <em>A Dance of Fire and Ice</em>, focused on performance, visual customization, and compatibility.</p><p>Project: <a href="https://github.com/adofaiex/Iridium" target="_blank" rel="noreferrer">https://github.com/adofaiex/Iridium</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="performance-optimization" tabindex="-1">Performance Optimization <a class="header-anchor" href="#performance-optimization" aria-label="Permalink to &quot;Performance Optimization&quot;">​</a></h3><ul><li>Rendering efficiency improvements, reducing stutter</li><li>Decoration texture compression, frame-by-frame loading (with progress)</li><li>Move Track / Move Decorations optimization (with freeroam support)</li><li>Particle optimization (object pooling / culling / LOD)</li><li>DOTween tuning, custom easing engine</li><li>Async input optimization, improving judgment precision</li></ul><h3 id="ui-visuals" tabindex="-1">UI &amp; Visuals <a class="header-anchor" href="#ui-visuals" aria-label="Permalink to &quot;UI &amp; Visuals&quot;">​</a></h3><ul><li>Remove news panel, hide beta watermark, adjust auto-demo text position</li><li>Editor countdown display</li><li>Lobby music: switch background music by BPM, support custom music paths</li><li>Judgment text customization (e.g. &quot;Perfect&quot;, &quot;Too Early&quot;), with rich text tags and offset display</li><li>Hit sound pitch follows music</li></ul><h3 id="editor-enhancements" tabindex="-1">Editor Enhancements <a class="header-anchor" href="#editor-enhancements" aria-label="Permalink to &quot;Editor Enhancements&quot;">​</a></h3><ul><li>Performance optimization for insert/delete operations on large levels (10k+ floors)</li><li>Custom hotkeys for decorations and floors</li><li>Auto-demo preview supports pause / resume</li></ul><h3 id="compatibility-fixes" tabindex="-1">Compatibility &amp; Fixes <a class="header-anchor" href="#compatibility-fixes" aria-label="Permalink to &quot;Compatibility &amp; Fixes&quot;">​</a></h3><ul><li>Ignore missing third-party Mod dependencies when loading levels (restores <code>requiredMods</code> on save)</li><li>Temporarily register unknown CustomEvents to avoid load crashes</li><li>Legacy level behavior options (Flash, Camera Relative, etc.)</li><li>Fix portal soft-lock, hairpin beat detection, editor replay error tracking</li></ul><h3 id="patch-modes" tabindex="-1">Patch Modes <a class="header-anchor" href="#patch-modes" aria-label="Permalink to &quot;Patch Modes&quot;">​</a></h3><ul><li><strong>IL Transpiler</strong>: performance-first</li><li><strong>Prefix/Postfix</strong>: compatibility-first</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a> installed</li><li>ADOFAI installed</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>For ADOFAI 2.10.0 and above, use <strong>UnityModManager 0.32.5.0 or later</strong>, otherwise crashes may occur.</p></div><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Go to <a href="https://github.com/Xbodwf/Iridium/releases" target="_blank" rel="noreferrer">Releases</a>, download the build <strong>matching your game version</strong> (each Release provides builds for multiple versions)</li><li>Extract to <code>A Dance of Fire and Ice/Mods/Iridium</code> (create the directory if it doesn&#39;t exist)</li><li>Launch the game; if the game is already running, restart it first</li></ol><h3 id="supported-game-versions" tabindex="-1">Supported Game Versions <a class="header-anchor" href="#supported-game-versions" aria-label="Permalink to &quot;Supported Game Versions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Game Version</th><th>Branch</th></tr></thead><tbody><tr><td>ADOFAI v2</td><td><code>v2</code> branch</td></tr><tr><td>ADOFAI v3</td><td><code>v3</code> branch</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Do not run Iridium on ADOFAI <strong>2.9.7 or below</strong>, except for versions specifically tuned for older game versions.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>After launch, the v3 settings are displayed in pages: <strong>General / Optimizer / Editor / Compatibility / Audio</strong> in the UMM settings panel (default <code>Ctrl+F10</code>).</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><blockquote><p>📝 To be supplemented (feel free to report in the repository Issues)</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Other loading methods: <a href="https://github.com/Xbodwf/Iridium/blob/main/docs/loader/melonloader.md" target="_blank" rel="noreferrer">MelonLoader</a> / <a href="https://github.com/Xbodwf/Iridium/blob/main/docs/loader/bepinex.md" target="_blank" rel="noreferrer">BepInEx</a></li></ul>',28)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
